//! Area href uses the shared original URL parser without navigation.
use super::*;
fn fixture()->(Document,Forms,Page){let mut d=crate::html::parse("<html><body><area id=area href=initial><input id=neighbor value=seed></body></html>");d.scripting_enabled=true;let mut f=Forms::new(&d);let mut p=Page::new();let location=crate::navigation::address("https://area-href.test/path/source",&crate::navigation::Location::home()).unwrap();p.set_location(&location);p.set_resource_base(&location);assert_eq!(p.start(&mut d,&mut f,&[]).errors,0);(d,f,p)}
fn run(d:&mut Document,f:&mut Forms,p:&mut Page,s:&str){p.runtime.execute(s,&mut Bridge{doc:d,forms:f,state:&mut p.state}).unwrap();}
#[test]
fn area_href_canonical_descriptor_and_initial_resolution(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var x=document.getElementById('area'),a=Object.getOwnPropertyDescriptor(HTMLAreaElement.prototype,'href');if(!a||!a.enumerable||!a.configurable||a.get.length!==0||a.set.length!==1||a.get.name!=='get href'||a.set.name!=='set href'||Object.hasOwn(x,'href')||x.href!=='https://area-href.test/path/initial'||x.getAttribute('href')!=='initial')throw 'canonical URL accessor';"#);}
#[test]
fn area_href_native_usv_raw_aliases_and_missing(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var x=document.getElementById('area'),a=x.getAttributeNode('href');x.href='../a b?\u00e4#part';if(x.href!=='https://area-href.test/a%20b?%C3%A4#part'||a.value!=='../a b?\u00e4#part'||x.getAttributeNode('href')!==a)throw 'shared parsed versus raw';x.href='https://example.test/\ud800';if(a.value!=='https://example.test/\ufffd'||x.href!=='https://example.test/%EF%BF%BD')throw 'USV setter';a.nodeValue='https://example.test/\udfff';if(x.href!=='https://example.test/%EF%BF%BD'||a.value!=='https://example.test/\udfff')throw 'raw Attr projection';x.href='http://[';if(x.href!=='http://['||a.value!=='http://[')throw 'invalid URL fallback';x.removeAttribute('href');if(x.href!==''||a.ownerElement!==null||a.value!=='http://[')throw 'missing URL';"#);}
#[test]
fn area_href_inert_current_base_once_conversion_namespace_and_clone(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var owner=document.implementation.createHTMLDocument(''),base=owner.createElement('base');base.setAttribute('href','https://first.test/path/');owner.head.appendChild(base);var x=owner.createElement('area');if(x.href!=='')throw 'inert missing';var calls=0;x.href={toString:function(){calls++;base.setAttribute('href','https://second.test/current/');return 'leaf';}};if(calls!==1||x.href!=='https://second.test/current/leaf'||x.getAttribute('href')!=='leaf')throw 'current base after once conversion';x.setAttributeNS('urn:foreign','href','foreign');x.setAttributeNS(null,'HREF','upper');var clone=x.cloneNode(false);if(clone.href!==x.href||clone.getAttribute('href')!=='leaf')throw 'namespace and independent clone';clone.href='https://third.test/';if(x.href!=='https://second.test/current/leaf'||clone.href!=='https://third.test/')throw 'independent raw URL';"#);}

#[test]
fn area_href_brands_anchor_separation_and_author_override(){
 let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var x=document.getElementById('area'),C=HTMLAreaElement,P=C.prototype,a=Object.getOwnPropertyDescriptor(P,'href'),anchor=document.createElement('a'),other=Object.getOwnPropertyDescriptor(HTMLAnchorElement.prototype,'href'),calls=0;for(var bad of [{},Object.create(P),document.body,anchor,document.createElementNS('urn:foreign','area')]){var caught=false;try{a.get.call(bad);}catch(e){caught=e instanceof TypeError;}if(!caught)throw 'genuine area getter brand';caught=false;try{a.set.call(bad,{toString:function(){calls++;return 'bad';}});}catch(e){caught=e instanceof TypeError;}if(!caught||calls)throw 'area brand precedes conversion';}var caught=false;try{other.get.call(x);}catch(e){caught=e instanceof TypeError;}if(!caught)throw 'anchor descriptor retains its brand';Object.defineProperty(x,'href',{value:'author',writable:true,configurable:true});a.set.call(x,'/canonical');if(x.href!=='author'||a.get.call(x)!=='https://area-href.test/canonical')throw 'canonical authority';delete x.href;delete window.HTMLAreaElement;if(x.href!=='https://area-href.test/canonical'||!(x instanceof C)||Object.getPrototypeOf(x)!==P)throw 'saved interface';"#);
}
#[test]
fn area_href_conversion_reentry_abrupt_symbol_and_no_navigation(){
 let(mut d,mut f,mut p)=fixture();let location=p.state.location.as_ref().map(|v|v.source.display());run(&mut d,&mut f,&mut p,r#"var x=document.getElementById('area'),old=x.getAttributeNode('href'),watch=new MutationObserver(function(){});watch.observe(x,{attributes:true,attributeOldValue:true});var calls=0;x.href={toString:function(){calls++;x.removeAttribute('href');x.setAttribute('href','author');return '../converted';}};var attr=x.getAttributeNode('href'),records=watch.takeRecords();if(calls!==1||attr===old||old.ownerElement!==null||old.value!=='initial'||attr.value!=='../converted'||x.href!=='https://area-href.test/converted'||records.length!==3||records[2].oldValue!=='author')throw 'current Attr after conversion';var marker={},caught;try{x.href={toString:function(){x.setAttribute('href','/effect');throw marker;}};}catch(e){caught=e;}if(caught!==marker||x.href!=='https://area-href.test/effect'||watch.takeRecords().length!==1)throw 'abrupt author effects';caught=false;try{x.href=Symbol('URL');}catch(e){caught=e instanceof TypeError;}if(!caught||watch.takeRecords().length||attr.value!=='/effect')throw 'symbol before mutation';"#);assert_eq!(p.state.location.as_ref().map(|v|v.source.display()),location);assert!(p.state.navigation.is_none());
}
#[test]
fn area_href_saved_child_origin_precedes_conversion_and_recovers(){
 let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var x=document.getElementById('area'),frame=document.createElement('iframe');frame.hidden=true;document.body.appendChild(frame);var a=Object.getOwnPropertyDescriptor(frame.contentWindow.HTMLAreaElement.prototype,'href'),calls=0;if(a.get.call(x)!=='https://area-href.test/path/initial')throw 'captured accessor';"#);
 p.set_location(&crate::navigation::address("https://other-href.test/",&crate::navigation::Location::home()).unwrap());let before=format!("{:?}",d.nodes);for code in ["a.get.call(x);","a.set.call(x,{toString:function(){calls++;return 'bad';}});"]{p.begin_job();let e=p.runtime.execute(code,&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).unwrap_err();assert!(e.contains("origin")||e.contains("Security"),"{e}");assert_eq!(format!("{:?}",d.nodes),before);}
 p.set_location(&crate::navigation::address("https://area-href.test/path/source",&crate::navigation::Location::home()).unwrap());p.begin_job();run(&mut d,&mut f,&mut p,"if(calls)throw 'origin before conversion';a.set.call(x,'/recovered');if(a.get.call(x)!=='https://area-href.test/recovered')throw 'fresh origin recovery';");
}
#[test]
fn area_href_writers_refuse_atomically_and_recover(){
 for inert in [false,true]{for writer in 0..5{for mode in 0..5{let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,if inert{"var x=new Document().createElementNS('http://www.w3.org/1999/xhtml','area');x.setAttribute('href','initial');"}else{"var x=document.getElementById('area');"});run(&mut d,&mut f,&mut p,"var attr=x.getAttributeNode('href'),watch=new MutationObserver(function(){});watch.observe(x,{attributes:true,attributeOldValue:true});");
 let code=match writer{0=>r"x.href='https://long.test/A\ud800Z';",1=>r"x.setAttribute('href','https://long.test/A\ud800Z');",2=>r"attr.value='https://long.test/A\ud800Z';",3=>r"attr.nodeValue='https://long.test/A\ud800Z';",_=>r"attr.textContent='https://long.test/A\ud800Z';"};
 p.state.rebuild(&d).unwrap();let before=format!("{:?}",d.nodes);let state=(p.state.retained,p.state.dom_commits,p.state.attributes.len(),p.state.detached_nodes.clone());let limit=p.state.retained_limit;let strings=p.state.limits.host.string_bytes;p.begin_job();match mode{0=>p.state.host_work=0,1=>p.state.copy_work=0,2=>p.state.retained_limit=p.state.retained,3=>p.state.limits.host.string_bytes=1,_=>p.state.execution_deadline=Some(Instant::now())};let e=p.runtime.execute(code,&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).unwrap_err();assert!(e.contains("work")||e.contains("allowance")||e.contains("limit")||e.contains("bound")||e.contains("time"),"{inert}/{writer}/{mode}: {e}");assert_eq!(format!("{:?}",d.nodes),before);assert_eq!((p.state.retained,p.state.dom_commits,p.state.attributes.len(),p.state.detached_nodes.clone()),state);
 p.state.retained_limit=limit;p.state.limits.host.string_bytes=strings;p.state.execution_deadline=None;p.begin_job();run(&mut d,&mut f,&mut p,"if(attr.value!=='initial'||watch.takeRecords().length)throw 'atomic URL writer refusal';");run(&mut d,&mut f,&mut p,code);run(&mut d,&mut f,&mut p,if writer==0{r"if(attr.value!=='https://long.test/A\ufffdZ')throw 'USV setter storage';"}else{r"if(attr.value!=='https://long.test/A\ud800Z')throw 'exact raw writer storage';"});run(&mut d,&mut f,&mut p,"var records=watch.takeRecords();if(x.href!=='https://long.test/A%EF%BF%BDZ'||records.length!==1||records[0].oldValue!=='initial'||records[0].attributeName!=='href'||x.getAttributeNode('href')!==attr)throw 'fresh URL writer recovery';");
 }}}
}
#[test]
fn area_href_reads_pay_parser_work_copy_string_and_deadline_without_mutation(){
 for inert in [false,true]{for mode in 0..5{let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,if inert{"var x=new Document().createElementNS('http://www.w3.org/1999/xhtml','area');x.href='https://example.test/source';"}else{"var x=document.getElementById('area');x.href='https://example.test/source';"});let Value::Host(object)=p.runtime.execute("x;",&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).unwrap()else{panic!("area handle")};let before=format!("{:?}",d.nodes);let state=(p.state.retained,p.state.dom_commits,p.state.attributes.len());let strings=p.state.limits.host.string_bytes;let limit=p.state.retained_limit;p.begin_job();match mode{0=>p.state.host_work=0,1=>p.state.copy_work=0,2=>p.state.limits.host.string_bytes=1,3=>p.state.execution_deadline=Some(Instant::now()),_=>p.state.retained_limit=p.state.retained};let result=Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}.area_href_get(object);if mode==4{assert!(matches!(result,Ok(Value::String(ref s))if s=="https://example.test/source"));}else{let e=result.unwrap_err();assert!(e.contains("work")||e.contains("allowance")||e.contains("bound")||e.contains("time"),"{e}");}assert_eq!(format!("{:?}",d.nodes),before);assert_eq!((p.state.retained,p.state.dom_commits,p.state.attributes.len()),state);p.state.limits.host.string_bytes=strings;p.state.retained_limit=limit;p.state.execution_deadline=None;p.begin_job();assert!(Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}.area_href_get(object).is_ok());}}
}
#[test]
fn area_href_raw_namespace_getter_observation_and_native_lifecycle_guards(){
 for inert in [false,true]{let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,if inert{"var x=new Document().createElementNS('http://www.w3.org/1999/xhtml','t:area');x.setAttribute('href','initial');"}else{"var x=document.getElementById('area');"});run(&mut d,&mut f,&mut p,r#"var attr=x.getAttributeNode('href'),watch=new MutationObserver(function(){});watch.observe(x,{attributes:true,attributeOldValue:true});for(var writer of ['value','nodeValue','textContent']){attr[writer]='https://example.test/R\udfff'+writer;if(x.href!=='https://example.test/R%EF%BF%BD'+writer||attr.value!=='https://example.test/R\udfff'+writer)throw 'raw aliases';}watch.takeRecords();x.setAttributeNS('urn:foreign','href','foreign');x.setAttributeNS(null,'HREF','upper');watch.takeRecords();if(x.href!=='https://example.test/R%EF%BF%BDtextContent'||attr.value!=='https://example.test/R\udffftextContent'||watch.takeRecords().length)throw 'pure getter with exact namespace';"#);if !inert{run(&mut d,&mut f,&mut p,"var copy=x.cloneNode(false),imported=document.importNode(new Document().createElementNS('http://www.w3.org/1999/xhtml','area'),false);if(copy.href!==x.href||copy.getAttributeNode('href').value!==attr.value||copy.getAttributeNode('href')===attr||copy.parentNode!==null||imported.ownerDocument!==document||imported.parentNode!==null||imported.href!==''||watch.takeRecords().length)throw 'independent native URL copies';");}else{let before=format!("{:?}",d.nodes);p.begin_job();let e=p.runtime.execute("document.importNode(x,false);",&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).unwrap_err();assert!(e.contains("unsupported namespaced attributes"),"{e}");assert_eq!(format!("{:?}",d.nodes),before);}}
}
